function beginObjectTransform(event,type){const item=selectedPlacedObject.value;if(!item)return;const center=screenPoint({x:item.x+.5,y:item.y+.5}),rect=mapViewport.value.getBoundingClientRect(),dx=event.clientX-rect.left-center.x,dy=event.clientY-rect.top-center.y;event.currentTarget.setPointerCapture?.(event.pointerId);transformDrag.value={type,centerX:center.x,centerY:center.y,startDistance:Math.max(1,Math.hypot(dx,dy)),startScale:item.scale||1,startAngle:Math.atan2(dy,dx)*180/Math.PI,startRotation:item.rotation||0};liveObjectTransform.value={x:item.x,y:item.y,scale:item.scale||1,rotation:item.rotation||0}}
function moveObjectTransform(event){const drag=transformDrag.value;if(!drag)return;const rect=mapViewport.value.getBoundingClientRect(),dx=event.clientX-rect.left-drag.centerX,dy=event.clientY-rect.top-drag.centerY;if(drag.type==='scale')liveObjectTransform.value={...liveObjectTransform.value,scale:Math.max(.25,Math.min(5,drag.startScale*Math.hypot(dx,dy)/drag.startDistance))};else{const angle=Math.atan2(dy,dx)*180/Math.PI;liveObjectTransform.value={...liveObjectTransform.value,rotation:((Math.round((drag.startRotation+angle-drag.startAngle)/5)*5)%360+360)%360}}}
async function finishObjectTransform(){if(!transformDrag.value)return;const patch={scale:liveObjectTransform.value.scale,rotation:liveObjectTransform.value.rotation};transformDrag.value=null;liveObjectTransform.value=null;await store.updateEntity(patch)}
function beginRoomTransform(event,type){const item=selectedRoom.value;if(!item)return;const worldCenter={x:item.x+item.width/2,y:item.y+item.height/2},center=screenPoint(worldCenter),rect=mapViewport.value.getBoundingClientRect(),dx=event.clientX-rect.left-center.x,dy=event.clientY-rect.top-center.y;event.currentTarget.setPointerCapture?.(event.pointerId);roomTransformDrag.value={type,centerX:center.x,centerY:center.y,worldCenterX:worldCenter.x,worldCenterY:worldCenter.y,startDistance:Math.max(1,Math.hypot(dx,dy)),startAngle:Math.atan2(dy,dx)*180/Math.PI,startRotation:item.rotation||0,startWidth:item.width,startHeight:item.height};liveRoomTransform.value={x:item.x,y:item.y,width:item.width,height:item.height,rotation:item.rotation||0}}
function moveRoomTransform(event){const drag=roomTransformDrag.value;if(!drag)return;const rect=mapViewport.value.getBoundingClientRect(),dx=event.clientX-rect.left-drag.centerX,dy=event.clientY-rect.top-drag.centerY;if(drag.type==='scale'){const minimumScale=Math.max(1/drag.startWidth,1/drag.startHeight),maximumScale=Math.min(80/drag.startWidth,80/drag.startHeight),scale=Math.max(minimumScale,Math.min(maximumScale,Math.hypot(dx,dy)/drag.startDistance)),width=Math.round(drag.startWidth*scale*4)/4,height=Math.round(drag.startHeight*scale*4)/4;liveRoomTransform.value={...liveRoomTransform.value,x:drag.worldCenterX-width/2,y:drag.worldCenterY-height/2,width,height}}else{const angle=Math.atan2(dy,dx)*180/Math.PI;liveRoomTransform.value={...liveRoomTransform.value,rotation:((Math.round((drag.startRotation+angle-drag.startAngle)/5)*5)%360+360)%360}}}
async function finishRoomTransform(){if(!roomTransformDrag.value)return;const patch={...liveRoomTransform.value};roomTransformDrag.value=null;liveRoomTransform.value=null;await store.updateEntity(patch)}
function beginLabelTransform(event,type){const item=selectedLabel.value;if(!item)return;const width=item.boxWidth||2,height=item.boxHeight||1,worldCenter={x:item.x+width/2,y:item.y+height/2},center=screenPoint(worldCenter),rect=mapViewport.value.getBoundingClientRect(),dx=event.clientX-rect.left-center.x,dy=event.clientY-rect.top-center.y;event.currentTarget.setPointerCapture?.(event.pointerId);labelTransformDrag.value={type,centerX:center.x,centerY:center.y,worldCenterX:worldCenter.x,worldCenterY:worldCenter.y,startDistance:Math.max(1,Math.hypot(dx,dy)),startAngle:Math.atan2(dy,dx)*180/Math.PI,startRotation:item.rotation||0,startWidth:width,startHeight:height,startFontSize:item.fontSize||LABEL_SIZES.find(({id})=>id===item.size)?.sceneSize||LABEL_SIZES[1].sceneSize};liveLabelTransform.value={x:item.x,y:item.y,boxWidth:width,boxHeight:height,fontSize:labelTransformDrag.value.startFontSize,rotation:item.rotation||0};const move=(next)=>moveLabelTransform(next),finish=()=>finishLabelTransform();window.addEventListener('pointermove',move);window.addEventListener('pointerup',finish,{once:true});window.addEventListener('pointercancel',finish,{once:true});labelTransformCleanup=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',finish);labelTransformCleanup=null}}
function moveLabelTransform(event){const drag=labelTransformDrag.value;if(!drag)return;const rect=mapViewport.value.getBoundingClientRect(),dx=event.clientX-rect.left-drag.centerX,dy=event.clientY-rect.top-drag.centerY;if(drag.type==='scale'){const minimumScale=Math.max(.35/drag.startFontSize,.5),maximumScale=Math.min(8/drag.startFontSize,10),scale=Math.max(minimumScale,Math.min(maximumScale,Math.hypot(dx,dy)/drag.startDistance)),boxWidth=drag.startWidth*scale,boxHeight=drag.startHeight*scale,fontSize=drag.startFontSize*scale;liveLabelTransform.value={...liveLabelTransform.value,x:drag.worldCenterX-boxWidth/2,y:drag.worldCenterY-boxHeight/2,boxWidth,boxHeight,fontSize}}else{const angle=Math.atan2(dy,dx)*180/Math.PI;liveLabelTransform.value={...liveLabelTransform.value,rotation:((Math.round((drag.startRotation+angle-drag.startAngle)/5)*5)%360+360)%360}}}
async function finishLabelTransform(){if(!labelTransformDrag.value)return;labelTransformCleanup?.();const patch={...liveLabelTransform.value};labelTransformDrag.value=null;liveLabelTransform.value=null;await store.updateEntity(patch)}
function beginLabelMove(event){const item=selectedLabel.value;if(!item||event.button!==0)return;event.currentTarget.setPointerCapture?.(event.pointerId);labelMoveDrag.value={startClientX:event.clientX,startClientY:event.clientY,startX:item.x,startY:item.y,moved:false};liveLabelTransform.value={x:item.x,y:item.y,boxWidth:item.boxWidth,boxHeight:item.boxHeight,fontSize:item.fontSize,rotation:item.rotation||0};const move=(next)=>moveLabel(next),finish=()=>finishLabelMove();window.addEventListener('pointermove',move);window.addEventListener('pointerup',finish,{once:true});window.addEventListener('pointercancel',finish,{once:true});labelMoveCleanup=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',finish);labelMoveCleanup=null}}
function moveLabel(event){const drag=labelMoveDrag.value;if(!drag)return;const x=snap(drag.startX+(event.clientX-drag.startClientX)/sceneScale.value),y=snap(drag.startY+(event.clientY-drag.startClientY)/sceneScale.value);drag.moved=drag.moved||x!==drag.startX||y!==drag.startY;liveLabelTransform.value={...liveLabelTransform.value,x,y}}
async function finishLabelMove(){if(!labelMoveDrag.value)return;labelMoveCleanup?.();const drag=labelMoveDrag.value,patch=liveLabelTransform.value?{x:liveLabelTransform.value.x,y:liveLabelTransform.value.y}:null;labelMoveDrag.value=null;liveLabelTransform.value=null;if(drag.moved&&patch)await store.updateEntity(patch)}
function objectSelectionStyle(){const item=sceneLiveObject.value||selectedPlacedObject.value;if(!item)return{};const asset=objectById[item.assetId]||{width:1,height:1},size=Math.max(asset.width,asset.height)*(item.scale||1)*sceneScale.value,center=screenPoint({x:item.x+.5,y:item.y+.5});return{left:`${center.x-size/2}px`,top:`${center.y-size/2}px`,width:`${size}px`,height:`${size}px`,transform:`rotate(${item.rotation||0}deg)`,'--counter-rotation':`${-(item.rotation||0)}deg`}}
function roomSelectionStyle(){const item=sceneLiveRoom.value||selectedRoom.value;if(!item)return{};const center=screenPoint({x:item.x+item.width/2,y:item.y+item.height/2});return{left:`${center.x-item.width*sceneScale.value/2}px`,top:`${center.y-item.height*sceneScale.value/2}px`,width:`${item.width*sceneScale.value}px`,height:`${item.height*sceneScale.value}px`,transform:`rotate(${item.rotation||0}deg)`,'--counter-rotation':`${-(item.rotation||0)}deg`}}
function labelSelectionStyle(){const item=sceneLiveLabel.value||selectedLabel.value;if(!item)return{};const width=item.boxWidth||8,height=item.boxHeight||2.25,center=screenPoint({x:item.x+width/2,y:item.y+height/2});return{left:`${center.x-width*sceneScale.value/2}px`,top:`${center.y-height*sceneScale.value/2}px`,width:`${width*sceneScale.value}px`,height:`${height*sceneScale.value}px`,transform:`rotate(${item.rotation||0}deg)`,'--counter-rotation':`${-(item.rotation||0)}deg`}}
function patchRoomNumber(key,event,min=.1,max=100){store.updateEntity({[key]:Math.max(min,Math.min(max,Number(event.target.value)||min))})}
function patchRoomWall(lineStyle){const style=LINE_STYLES.find((item)=>item.id===lineStyle)||LINE_STYLES[0];store.updateEntity({lineStyle:style.id,wallTerrain:style.terrain,wallWidth:style.width})}
function zoomTo(next){store.zoom=Math.max(.25,Math.min(3,next))}
function wheelZoom(event){if(spacePressed.value){const unit=event.deltaMode===1?16:event.deltaMode===2?mapViewport.value.clientHeight:1;camera.value={x:camera.value.x+event.deltaX*unit/sceneScale.value,y:camera.value.y+event.deltaY*unit/sceneScale.value};return}const worldPoint=pointerPoint(event),rect=mapViewport.value.getBoundingClientRect(),screenX=event.clientX-rect.left-rect.width/2,screenY=event.clientY-rect.top-rect.height/2;zoomTo(store.zoom*Math.exp(-event.deltaY*.0015));camera.value={x:worldPoint.x-screenX/sceneScale.value,y:worldPoint.y-screenY/sceneScale.value}}
function fitContent(){if(!mapViewport.value)return;const bounds=store.contentBounds,rect=mapViewport.value.getBoundingClientRect(),next=Math.max(.25,Math.min(1.5,(rect.width-160)/(bounds.width*cellSize.value),(rect.height-190)/(bounds.height*cellSize.value)));store.zoom=Math.round(next*20)/20;camera.value={x:(bounds.minX+bounds.maxX+1)/2,y:(bounds.minY+bounds.maxY+1)/2}}
function chooseTool(tool){store.activeTool=tool.id;store.selection=null;cancelInteraction();if(['terrain','room','wall','object','erase','label'].includes(tool.id))openPanel.value=openPanel.value===tool.id?null:tool.id;else openPanel.value=null}
function selectLineStyle(style){store.selectedLineStyle=style.id}
async function persistDraftLabel(values,editing){
  const save=async()=>{if(editing){store.selection={kind:'label',id:editing};if(!store.selectedEntity)throw Object.assign(new Error('This label no longer exists'),{code:'not_found'});await store.updateEntity(values)}else await store.addLabels([values])}
  try{await save()}catch(error){
    if(error?.code!=='version_conflict')throw error
    await store.openProject(project.value.id)
    await save()
  }
}
async function commitDraftLabel(){
  if(!draftLabelBox.value||savingLabel.value)return false
  const text=labelText.value.trim(),editing=editingLabelId.value
  if(!text){cancelDraftLabel();return true}
  fitDraftLabelToText();const fitted={...draftLabelBox.value}
  const values={text,x:fitted.left,y:fitted.top,boxWidth:fitted.width,boxHeight:fitted.height,fontSize:labelFontSize.value,rotation:labelRotation.value,size:labelSize.value,font:labelFont.value,color:labelColor.value,bold:labelBold.value}
  savingLabel.value=true;labelSaveError.value=''
  try{
    await persistDraftLabel(values,editing)
    draftLabelBox.value=null;editingLabelId.value=null;labelAnchor.value=null;labelText.value='';store.activeTool='select';openPanel.value=null
    return true
  }catch(error){
    labelSaveError.value=error?.code==='not_found'?'That label was removed in another tab. Your text is still here.':'Could not save yet. Your text is still here—click outside to retry.'
