async function pasteCopiedObject(){if(!copiedObject)return false;pasteCount+=1;const offset=pasteCount*.5,created=await store.placeObjects([{...copiedObject,x:snap(copiedObject.x+offset),y:snap(copiedObject.y+offset)}]);if(!created.length)pasteCount-=1;else{store.activeTool='select';openPanel.value=null}return Boolean(created.length)}
