function handleKeydown(event){if(event.key==='Escape'){event.preventDefault();if(draftLabelBox.value){cancelDraftLabel();releaseSpace();return}openPanel.value=null;store.selection=null;store.activeTool='select';cancelInteraction();releaseSpace();return}if(isTypingTarget(event.target))return;const modifier=event.metaKey||event.ctrlKey,key=event.key.toLowerCase(),isZ=key==='z'||event.code==='KeyZ',isY=key==='y'||event.code==='KeyY',isC=key==='c'||event.code==='KeyC',isV=key==='v'||event.code==='KeyV';if(event.code==='Space'&&!modifier&&!event.altKey){event.preventDefault();spacePressed.value=true;return}if(modifier&&isC&&copySelectedObject()){event.preventDefault();return}if(modifier&&isV&&copiedObject){event.preventDefault();if(!event.repeat)pasteCopiedObject();return}if(!modifier&&!event.altKey&&shortcutTools[key]){event.preventDefault();if(!event.repeat){const toolId=shortcutTools[key];store.activeTool=toolId;store.selection=null;cancelInteraction();openPanel.value=['terrain','room','wall','object','erase','label'].includes(toolId)?toolId:null}return}if(modifier&&isZ&&!event.shiftKey){event.preventDefault();if(!event.repeat)store.undo();return}if(modifier&&(isY||(isZ&&event.shiftKey))){event.preventDefault();if(!event.repeat)store.redo();return}if(modifier&&(['+','=','Add'].includes(event.key)||event.code==='Equal')){event.preventDefault();zoomTo(store.zoom+.1);return}if(modifier&&(['-','_','Subtract'].includes(event.key)||event.code==='Minus')){event.preventDefault();zoomTo(store.zoom-.1);return}if(!modifier&&!event.altKey&&['Backspace','Delete'].includes(event.key)&&store.selection){event.preventDefault();store.deleteSelection()}}
