        <p class="tool-hint shape-draw-hint">{{roomAnchor?'Drag to size the shape, then release.':'Drag on the map to draw with this combination.'}}</p>
      </div>
      <template v-else-if="openPanel!=='erase'"><label class="asset-search"><Search aria-hidden="true"/><input v-model="assetSearch" type="search" :placeholder="openPanel==='object'?'Search objects':'Search textures'" :aria-label="openPanel==='object'?'Search objects':'Search textures'"></label><div class="asset-browser"><section v-for="group in groupedPickerAssets" :key="group.category" class="asset-category"><h3>{{group.category}}</h3><div :class="['asset-grid',openPanel==='object'?'object-assets':'terrain-assets']"><button v-for="asset in group.assets" :key="asset.id" :class="['asset-button',{active:openPanel==='object'?store.selectedObject===asset.id:store.selectedTerrain===asset.id}]" :title="openPanel==='object'?`${asset.label} · ${asset.width} × ${asset.height}`:asset.label" @click="openPanel==='object'?store.selectedObject=asset.id:store.selectedTerrain=asset.id"><span :class="openPanel==='object'?'object-swatch':'terrain-swatch'" :style="spriteStyle(asset.sprite)"></span><small>{{asset.label}}</small></button></div></section><p v-if="!groupedPickerAssets.length" class="asset-empty">No matching {{openPanel==='object'?'objects':'textures'}}.</p></div></template>
      <div v-if="openPanel!=='room'" class="picker-controls"><label v-if="openPanel==='wall'" class="brush-control"><span>Line width</span><input v-model.number="store.lineWidth" type="range" min="0.12" max="1.5" step="0.02" aria-label="Line width"><output>{{store.lineWidth.toFixed(2)}} cells</output></label><label v-if="['terrain','erase'].includes(openPanel)" class="brush-control"><span>Brush diameter</span><input :value="store.brushSize" type="range" min="1" max="24" step="1" aria-label="Brush diameter" @input="store.brushSize=Number($event.target.value)"><output>{{store.brushSize}} cells</output></label><label v-if="['terrain','erase'].includes(openPanel)" class="brush-control"><span>Softness</span><input :value="activeSoftness" type="range" min="0" max="100" step="5" :aria-label="store.activeTool==='erase'?'Eraser softness':'Brush softness'" @input="setActiveSoftness"><output>{{activeSoftness}}%</output></label></div>
    </section>
    <section v-if="openPanel==='label'" ref="assetPanel" class="floating-panel label-panel draggable-panel" :class="{'is-dragging':pickerDrag}" :style="assetPanelStyle"><header class="picker-drag-handle" title="Drag to move" aria-label="Drag panel to move" @pointerdown.stop.prevent="beginPickerDrag" @pointermove.stop.prevent="movePickerDrag" @pointerup.stop.prevent="finishPickerDrag" @pointercancel.stop.prevent="finishPickerDrag"><GripHorizontal class="picker-grip" aria-hidden="true"/><div><strong>Text style</strong><small>Choose a map typeface and color</small></div><button class="icon-button" title="Close" aria-label="Close" @click="openPanel=null"><X/></button></header><div class="label-fields"><div class="field"><label>Typeface</label><div class="label-font-options"><button v-for="option in labelFontOptions" :key="option.id" type="button" :class="{active:labelFont===option.id}" :style="{fontFamily:option.family}" :aria-label="option.label" :aria-pressed="labelFont===option.id" @click="labelFont=option.id">{{option.label}}</button></div></div><label class="label-color-picker"><span>Color</span><input v-model="labelColor" type="color" aria-label="Label color"><output>{{labelColor.toUpperCase()}}</output></label><p class="label-placement-hint">Click the map and type. The label fits your text automatically.</p></div></section>
    <section v-if="openPanel==='layers'" class="floating-panel side-panel"><header><div><strong>Map layers</strong><small>Control what appears in the editor</small></div><button class="icon-button" title="Close" @click="openPanel=null"><X/></button></header><div class="layer-list"><button v-for="layer in [...store.bundle.layers].reverse()" :key="layer.id" @click="store.toggleLayer(layer.id)"><Eye v-if="layer.visible"/><EyeOff v-else/><span><strong>{{layer.name}}</strong><small>{{layer.kind}}</small></span></button></div><div class="map-summary"><Map/><div><strong>Continuous canvas</strong><span>{{store.contentBounds.width}} × {{store.contentBounds.height}} occupied · {{store.visibleObjects.length}} objects</span></div></div></section>
    <section v-if="openPanel==='selection'&&store.selectedEntity" class="floating-panel side-panel selection-panel"><header><div><small class="modal-eyebrow">{{store.selection.kind==='room'?'shape':store.selection.kind}}</small><strong>{{store.selection.kind==='object'?objectById[store.selectedEntity.assetId]?.label:store.selection.kind==='room'?'Shape':store.selectedEntity.text}}</strong></div><button class="icon-button" title="Close" @click="openPanel=null"><X/></button></header><template v-if="store.selection.kind==='label'"><div class="field"><label>Typeface</label><div class="label-font-options"><button v-for="option in labelFontOptions" :key="option.id" type="button" :class="{active:store.selectedEntity.font===option.id}" :style="{fontFamily:option.family}" :aria-label="'Use '+option.label" :aria-pressed="store.selectedEntity.font===option.id" @click="store.updateEntity({font:option.id})">{{option.label}}</button></div></div><label class="label-color-picker"><span>Color</span><input :value="resolveLabelColor(store.selectedEntity.color).value" type="color" aria-label="Selected label color" @input="store.updateEntity({color:$event.target.value})"><output>{{resolveLabelColor(store.selectedEntity.color).value.toUpperCase()}}</output></label></template><template v-if="store.selection.kind==='room'"><div class="field"><label>Shape</label><select :value="store.selectedEntity.shape||'rectangle'" aria-label="Selected shape type" @change="store.updateEntity({shape:$event.target.value})"><option value="rectangle">Rectangle</option><option value="ellipse">Ellipse</option><option value="polygon">Polygon</option><option value="star">Star</option></select></div><div v-if="['polygon','star'].includes(store.selectedEntity.shape)" class="field"><label>Points</label><input :value="store.selectedEntity.sides" aria-label="Selected shape points" type="number" min="3" max="12" @change="patchRoomNumber('sides',$event,3,12)"></div><div class="field"><label>Floor texture</label><select :value="store.selectedEntity.floorTerrain" aria-label="Shape fill texture" @change="store.updateEntity({floorTerrain:$event.target.value})"><option v-for="terrain in TERRAIN" :key="terrain.id" :value="terrain.id">{{terrain.label}}</option></select></div><div class="field"><label>Wall type</label><select :value="store.selectedEntity.lineStyle||'stone-wall'" aria-label="Selected shape wall type" @change="patchRoomWall($event.target.value)"><option v-for="style in LINE_STYLES" :key="style.id" :value="style.id">{{style.label}}</option></select></div><label class="brush-control shape-wall-width"><span>Wall thickness</span><input :value="store.selectedEntity.wallWidth||.52" type="range" min="0.12" max="1.5" step="0.02" aria-label="Shape wall thickness" @change="patchRoomNumber('wallWidth',$event,.12,1.5)"><output>{{(store.selectedEntity.wallWidth||.52).toFixed(2)}} cells</output></label></template><button class="button danger inspector-delete" @click="store.deleteSelection"><Trash2/>Remove from map</button></section>
    <MapShortcutModal v-if="shortcutsOpen" :tools="primaryTools" :shortcuts="toolShortcuts" @close="shortcutsOpen=false"/>
    <MapToolDock :tools="primaryTools" :active-tool="store.activeTool" :selected-kind="store.selection?.kind" :selection-open="openPanel==='selection'" :shortcuts="toolShortcuts" :labels="toolDockLabels" @choose="chooseTool" @toggle-selection="openPanel=openPanel==='selection'?null:'selection'"/>
  </section></section></main>
</template>
